function [tau] = damp_torque(kd, w)
%DAMP_TORQUE  The torque -kd e against the excess rate (kd the rotor loop's rate gain).
%   kd: real[1][3] (passed a plain number)
%   w: real[1][3] (passed a plain number)
%   returns tau: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    tau = zeros(3, 1);
    e = asils.alg.steplaws.damp_excess(w);
    i = ((0):((3) - 1)).';
    tau((i) + 1) = ((-(reshape(kd((i) + 1), [], 1))) .* reshape(e((i) + 1), [], 1));
end
